def _plan_order(graph, roots):
    needed = set()

    def collect(node):
        if node in needed:
            return
        needed.add(node)
        for dep in graph[node]["deps"]:
            collect(dep)

    for root in roots:
        collect(root)
    planned = []
    while True:
        candidates = [n for n in needed if graph[n]["digest"] is None and n not in planned and all((d not in needed or graph[d]["digest"] is not None or d in planned) for d in graph[n]["deps"])]
        if not candidates:
            break
        candidates.sort(key=lambda n: (-graph[n]["priority"], n))
        node = candidates[0]
        planned.append(node)
        graph[node]["digest"] = graph[node]["digest"] or _digest_for(graph, node)
    return planned

